{
 "app_name": "venmo",
 "api_name": "login",
 "path": "/auth/token",
 "method": "POST",
 "description": "Login to your account.",
 "parameters": [
  {
   "name": "username",
   "type": "string",
   "required": true,
   "description": "Your account email.",
   "default": null,
   "constraints": []
  },
  {
   "name": "password",
   "type": "string",
   "required": true,
   "description": "Your account password.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "access_token": "string",
   "token_type": "string"
  },
  "failure": {
   "message": "string"
  }
 }
}
{
 "app_name": "venmo",
 "api_name": "show_received_payment_requests",
 "path": "/received_payment_requests",
 "method": "GET",
 "description": "Get a list of payment requests you have received from others.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "status",
   "type": "string",
   "required": false,
   "description": "Filter payment requests by status. Will skip filtering if not passed.",
   "default": null,
   "constraints": [
    "value in ['pending', 'approved', 'denied']"
   ]
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1.0, <= 20.0"
   ]
  }
 ],
 "response_schemas": {
  "success": [
   {
    "payment_request_id": 1,
    "amount": 0.0,
    "description": "string",
    "created_at": "2019-01-01T00:00:00",
    "updated_at": "2019-01-01T00:00:00",
    "approved_at": "2019-01-01T00:00:00",
    "denied_at": "2019-01-01T00:00:00",
    "private": true,
    "sender": {
     "name": "string",
     "email": "user@example.com"
    },
    "receiver": {
     "name": "string",
     "email": "user@example.com"
    }
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}
{
 "app_name": "venmo",
 "api_name": "approve_payment_request",
 "path": "/payment_requests/{payment_request_id}/approve",
 "method": "POST",
 "description": "Approve a payment request.",
 "parameters": [
  {
   "name": "payment_request_id",
   "type": "integer",
   "required": true,
   "description": "ID of the payment request to approve.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "payment_card_id",
   "type": "integer",
   "required": false,
   "description": "ID of the payment card to use for approving the payment request. If not passed, Venmo balance will be used.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string"
  },
  "failure": {
   "message": "string"
  }
 }
}
{
 "app_name": "venmo",
 "api_name": "show_venmo_balance",
 "path": "/balance",
 "method": "GET",
 "description": "Show your Venmo balance.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "venmo_balance": 0.0
  },
  "failure": {
   "message": "string"
  }
 }
}
{
 "app_name": "venmo",
 "api_name": "withdraw_from_venmo_balance",
 "path": "/balance",
 "method": "DELETE",
 "description": "Withdraw money from your Venmo balance.",
 "parameters": [
  {
   "name": "amount",
   "type": "number",
   "required": true,
   "description": "Amount to withdraw from Venmo balance.",
   "default": null,
   "constraints": [
    "value > 0.0"
   ]
  },
  {
   "name": "payment_card_id",
   "type": "integer",
   "required": true,
   "description": "ID of the payment card to credit the withdrawn amount to.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string",
   "bank_transfer_id": 1
  },
  "failure": {
   "message": "string"
  }
 }
}
{
 "app_name": "venmo",
 "api_name": "show_payment_cards",
 "path": "/payment_cards",
 "method": "GET",
 "description": "Get a list of users payment cards.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   {
    "payment_card_id": 1,
    "card_name": "string",
    "owner_name": "string",
    "card_number": 1000000000000000.0,
    "expiry_year": 1,
    "expiry_month": 1.0,
    "cvv_number": 100.0
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}

